{
  "name": "magpie-junie",
  "version": "0.1.2",
  "description": "OpenCode provider plugin: JetBrains Junie for magpie (CLI credential reuse, browser PKCE, API key)",
  "type": "module",
  "main": "./index.mjs",
  "bin": {
    "magpie-junie-bridge": "./bridge-server.mjs"
  },
  "files": [
    "index.mjs",
    "bridge-server.mjs",
    "lib",
    "icon.svg",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "magpie",
    "magpie-plugin",
    "junie",
    "jetbrains",
    "grazie",
    "auth",
    "provider"
  ],
  "license": "MIT",
  "author": "aqiu817",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/aqiu817/magpie-junie.git"
  },
  "homepage": "https://github.com/aqiu817/magpie-junie#readme",
  "bugs": "https://github.com/aqiu817/magpie-junie/issues",
  "magpie": {
    "name": "Junie",
    "icon": "data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2024%2024'%3E%3Crect%20width='24'%20height='24'%20rx='5'%20fill='%23000'%2F%3E%3Cpath%20fill='%23fff'%20d='M6%206h3l6%206V6h3v12h-3L9%2012v6H6z'/%3E%3C%2Fsvg%3E",
    "maxConcurrency": 2,
    "summary": {
      "en": "Use your JetBrains Junie subscription in magpie. Reuse the local CLI login, browser PKCE, or a perm-* key.",
      "zh": "在 magpie 中使用 JetBrains Junie：复用本机 CLI 登录态、浏览器登录或 perm-* API key。"
    }
  },
  "publishConfig": {
    "registry": "https://registry.npmjs.org"
  },
  "scripts": {
    "test": "node --test test/*.test.mjs"
  }
}

// magpie-junie：把 JetBrains Junie 接入 magpie 供应商 `junie`。
//
// 三种登录方式（按优先级）：
//   1. 导入本机 CLI 登录态（~/.junie/dpapi_credentials，DPAPI 解密）——最快，不用浏览器
//   2. 浏览器 PKCE（Junie CLI 同款）——没有本地 CLI 时用
//   3. API key（perm-*，从 junie.jetbrains.com/cli 获取）——兜底
//
// 请求链路（两种，由 options.bridgeUrl 选择）：
//   A. 直连上游：loader.fetch 把标准请求发到 ingrazzio-cloud-prod.labs.jb.gg
//      （见 lib/fetch.mjs）。需代理，且账号要有有效订阅；license=NONE 会被 403。
//   B. 本地桥接（推荐给 free tier）：options.bridgeUrl 指向 bridge-server.mjs，
//      后端调 CLI headless 的 junie-lite 通道（见 bridge-server.mjs）。
//
// 注意：上游对中国 IP 直连返回 403，需宿主/Node 开启代理（NODE_USE_ENV_PROXY=1）。

import { PROVIDER, DISPLAY_NAME } from "./lib/constants.mjs"
import { MODELS, configModels } from "./lib/models.mjs"
import { readCliCredentials } from "./lib/credentials.mjs"
import { startPkceLogin, refreshAccessToken } from "./lib/auth.mjs"
import { makeFetch } from "./lib/fetch.mjs"
import { usageHook } from "./lib/usage.mjs"
import { proxyFetch } from "./lib/proxy.mjs"

const MAX_CONCURRENCY = 2

/** 把 CLI 凭据或 PKCE 结果规范化成 magpie 的 success 结果。 */
function success(auth) {
  return { type: "success", ...auth }
}

export async function JuniePlugin(input, options = {}) {
  // plugins.json 里该插件项的 options，闭包捕获，所有 hook 共用。
  const pluginOptions = options ?? {}
  return {
    config: async (cfg = {}) => {
      cfg.provider ??= {}
      // 桥接模式下只暴露 CLI 能跑的模型。
      const opts = pluginOptions
      const models = opts.bridgeUrl
        ? { "junie-lite": { name: "Junie Lite (CLI)", limit: { context: 262144, output: 16384 }, tool_call: true } }
        : configModels(opts)
      cfg.provider[PROVIDER] ??= {
        name: DISPLAY_NAME,
        npm: "@ai-sdk/openai-compatible", // chat completions
        api: opts.bridgeUrl ?? "https://ingrazzio-cloud-prod.labs.jb.gg/v1",
        models,
      }
    },

    auth: {
      provider: PROVIDER,
      maxConcurrency: MAX_CONCURRENCY,
      refreshLead: 90_000,

      methods: [
        {
          type: "api",
          label: "从本机 Junie CLI 导入登录态",
          async authorize() {
            const r = await readCliCredentials()
            if (!r.ok) {
              return { type: "failed", error: `未找到可用的 Junie CLI 登录态（${r.reason}）。` }
            }
            // api 的 authorize 支持直接返回 success（文档明确）；把 CLI 的 OAuth
            // token 打包成 key 存起来。桥接模式不用它鉴权，但保留供直连模式使用。
            return {
              type: "success",
              key: r.auth.access,
              metadata: {
                ...(r.auth.metadata ?? {}),
                cliAuth: r.auth,
              },
            }
          },
        },
        {
          type: "oauth",
          label: "浏览器登录（JetBrains 账号）",
          async authorize() {
            try {
              const r = await startPkceLogin()
              return {
                url: r.url,
                instructions: r.instructions,
                method: r.method,
                callback: r.callback,
              }
            } catch (err) {
              return { type: "failed", error: `无法开始登录：${String(err?.message ?? err).slice(0, 500)}` }
            }
          },
        },
        {
          type: "api",
          label: "Junie API key (perm-*)",
          placeholder: "perm-…",
        },
      ],

      async loader(getAuth, provider) {
        const auth = await getAuth().catch(() => null)
        // options 来自 plugins.json 的该项；magpie 也可能把它挂在 provider.options 上。
        const options = { ...pluginOptions, ...(provider?.options ?? {}) }
        if (options.bridgeUrl) {
          // 本地桥接模式：后端是 CLI headless，它自己持有 Junie 登录态，
          // 所以这里**不要求 magpie 侧登录**，任何账号状态都能转发。
          const base = String(options.bridgeUrl).replace(/\/+$/, "")
          return {
            baseURL: base,
            apiKey: "local",
            fetch: (input, init) => {
              const u = new URL(String(input))
              const target = new URL(base)
              u.protocol = target.protocol
              u.host = target.host
              return proxyFetch(u.toString(), init, { proxy: false })
            },
          }
        }
        return {
          baseURL: "https://ingrazzio-cloud-prod.labs.jb.gg/v1",
          apiKey: auth.access ?? auth.key,
          fetch: makeFetch(auth, options),
        }
      },

      async refresh(auth) {
        return refreshAccessToken(auth)
      },

      async usage(getAuth) {
        return usageHook(getAuth)
      },
    },

    provider: {
      id: PROVIDER,
      async models(providerModels, { auth } = {}) {
        if (pluginOptions.bridgeUrl) {
          return { "junie-lite": { name: "Junie Lite (CLI)", limit: { context: 262144, output: 16384 }, tool_call: true } }
        }
        // 模型目录来自 junie-api 抓包快照；真机探测到新 id 时在这里合并。
        // 失败时保留原列表（magpie 约定）。
        if (!auth) return providerModels
        return { ...providerModels, ...configModels() }
      },
    },
  }
}

// 入口纪律：只导出插件函数 + default；辅助函数放 lib/ 和 _internal。
export const _internal = { MODELS, configModels, readCliCredentials, startPkceLogin, makeFetch, usageHook }

export default { id: PROVIDER, server: JuniePlugin }
